    function payFee(order){return Number((order.paid*.0025).toFixed(2))}
    function splitFee(order){return Number((order.merchantShare*.001).toFixed(2))}
    function financeRows(){var result=orders.map(function(order){var station=stationById(order.stationId);return {id:'ZD'+order.id.slice(2),orderId:order.id,merchantOrder:'SL'+order.id.slice(-10),operator:order.operator,stationId:order.stationId,station:station?station.name:'—',direction:'收入',billType:order.payment==='钱包支付'?'钱包消费':'充电订单',electricity:order.electricity,service:order.service,discount:order.discount,amount:order.paid,paymentFee:payFee(order),shareFee:splitFee(order),merchant:order.merchantShare,platform:Number((order.paid-order.merchantShare-payFee(order)).toFixed(2)),date:order.created.slice(0,10),time:order.created,status:'已到账'}});recharges.forEach(function(item){result.push({id:'ZD'+item.id.slice(2),orderId:item.id,merchantOrder:'SL'+item.id.slice(-8),operator:'—',stationId:'',station:'—',direction:item.kind==='个人钱包充值'?'内部划转':'收入',billType:item.kind==='个人钱包充值'?'钱包充值':'企业充值',electricity:0,service:0,discount:0,amount:item.amount,paymentFee:item.kind==='个人钱包充值'?Number((item.amount*.0025).toFixed(2)):0,shareFee:0,merchant:0,platform:0,date:item.time.slice(0,10),time:item.time,status:item.status})});refunds.filter(function(item){return item.status==='已退款'}).forEach(function(refund){var order=orderById(refund.orderId);result.push({id:'ZD'+refund.id.slice(2),orderId:refund.orderId,merchantOrder:'SL'+refund.id.slice(-8),operator:order.operator,stationId:order.stationId,station:stationById(order.stationId).name,direction:'支出',billType:'订单退款',electricity:0,service:0,discount:0,amount:refund.amount,paymentFee:0,shareFee:0,merchant:0,platform:0,date:refund.time.slice(0,10),time:refund.time,status:'已退款'})});return result}
    function renderFinance(){var records=financeRows().filter(match),income=records.filter(function(item){return item.billType==='充电订单'||item.billType==='钱包消费'}).reduce(function(sum,item){return sum+item.amount},0),wallet=records.filter(function(item){return item.billType==='钱包充值'}).reduce(function(sum,item){return sum+item.amount},0),actions='<button class="btn" data-action="export">导出 Excel</button>';$('content').innerHTML=metrics([{label:'充电经营收入',value:money(income),unit:'元',icon:'¥'},{label:'钱包充值资金',value:money(wallet),unit:'元',icon:'◉',note:'充值余额不计入经营收入'},{label:'支付手续费 0.25%',value:money(records.reduce(function(sum,item){return sum+item.paymentFee},0)),unit:'元',icon:'%'},{label:'分账手续费 0.1%',value:money(records.reduce(function(sum,item){return sum+item.shareFee},0)),unit:'元',icon:'%'}])+'<section class="surface">'+querybar('订单编号 / 账单编号 / 商户订单号')+toolbar('收支明细',records.length,actions)+renderTable(['账单日期','账单编号','订单编号','商户订单号','所属运营商','收支类型','账单类型','电费 (元)','服务费 (元)','优惠 (元)','账单金额 (元)','支付手续费 (元)','分账手续费 (元)','运营商应收 (元)','平台应收 (元)','到账状态'],records,function(item){return '<tr><td>'+item.date+'</td><td class="code">'+item.id+'</td><td class="code">'+item.orderId+'</td><td class="code">'+item.merchantOrder+'</td><td>'+esc(item.operator)+'</td><td>'+esc(item.direction)+'</td><td>'+esc(item.billType)+'</td><td>'+money(item.electricity)+'</td><td>'+money(item.service)+'</td><td>'+money(item.discount)+'</td><td>'+money(item.amount)+'</td><td>'+money(item.paymentFee)+'</td><td>'+money(item.shareFee)+'</td><td>'+money(item.merchant)+'</td><td>'+money(item.platform)+'</td><td>'+badge(item.status)+'</td><td class="actions">'+actionButton('finance',item.orderId)+'</td></tr>'})+'</section>'}
