    function merchantRecon(){return operators.map(function(operator,index){var owned=orders.filter(function(order){return order.operator===operator}),gross=owned.reduce(function(sum,item){return sum+item.electricity+item.service},0),discount=owned.reduce(function(sum,item){return sum+item.discount},0),refund=refunds.filter(function(item){var order=orderById(item.orderId);return order&&order.operator===operator&&item.status==='已退款'}).reduce(function(sum,item){return sum+item.amount},0),merchant=owned.reduce(function(sum,item){return sum+item.merchantShare},0),fee=owned.reduce(function(sum,item){return sum+splitFee(item)},0),difference=index===1?1.8:0;return {id:'DZ'+String(index+1).padStart(4,'0'),operator:operator,settlement:index===2?'线下结算':'自动结算',date:'2026-08-25',orders:owned.length,gross:gross,discount:discount,refund:refund,merchant:merchant,fee:fee,actual:Number((merchant-fee-difference).toFixed(2)),arrival:'2026-08-25 18:30',difference:difference}})}
    function platformRecon(){var grouped={};orders.forEach(function(order){var date=order.created.slice(0,10);if(!grouped[date])grouped[date]={id:'PT'+date.replace(/-/g,''),date:date,count:0,quantity:0,electricity:0,service:0,discount:0,refund:0,paymentFee:0,shareFee:0,gross:0,platform:0};var item=grouped[date];item.count++;item.quantity+=order.quantity;item.electricity+=order.electricity;item.service+=order.service;item.discount+=order.discount;item.refund+=order.refund;item.paymentFee+=payFee(order);item.shareFee+=splitFee(order);item.gross+=order.paid;item.platform+=order.paid-order.merchantShare-payFee(order)});return Object.keys(grouped).sort().reverse().map(function(key){var row=grouped[key];row.difference=row.date==='2026-08-24'?1.8:0;return row})}
