    function pileDetailBody(pile){var station=stationById(pile.stationId);if(state.detailTab==='设备信息')return '<div class="info-grid">'+info('设备编码',pile.id)+info('充电桩名称',esc(pile.name))+info('所属运营商',esc(pile.operator))+info('所属场站',esc(station.name))+info('设备厂商',esc(pile.brand))+info('设备类型',pile.type)+info('设备状态',badge(pile.status))+info('启用状态',badge(pile.enabled?'启用':'停用'))+info('工作功率',pile.power+' kW')+info('工作电压',pile.voltage+' V')+info('工作电流',pile.current+' A')+info('最大允许输出功率',pile.maxOutput+'%')+info('物联网卡号',pile.iot)+info('协议版本',pile.protocol)+info('设备版本号',pile.version)+info('创建时间',pile.created)+info('离线时间',pile.offline)+'</div>';if(state.detailTab==='充电枪')return '<div class="device-cards">'+guns.filter(function(item){return item.pileId===pile.id}).map(deviceCard).join('')+'</div>';if(state.detailTab==='充电订单')return simpleTable(['订单编号','用户','充电量 (kWh)','用户实付 (元)','订单状态'],orders.filter(function(order){return order.pileId===pile.id}).map(function(order){return [order.id,userById(order.userId).phone,String(order.quantity),money(order.paid),badge(order.status)]}));return simpleTable(['日志编号','命令类型','请求数据','请求报文','日志时间','发送状态'],logs.filter(function(log){return log.pileId===pile.id}).map(function(log){return [log.id,esc(log.type),esc(log.request),esc(log.message),log.time,badge(log.status)]}))}
    function gunDetailBody(gun){var pile=pileById(gun.pileId),station=stationById(gun.stationId);if(state.detailTab==='设备信息')return '<div class="info-grid">'+info('枪编号',gun.id)+info('所属充电桩',esc(pile.name))+info('所属场站',esc(station.name))+info('所属运营商',esc(gun.operator))+info('枪类型',esc(gun.type))+info('枪状态',badge(gun.status))+info('当前电压',gun.voltage+' V')+info('当前电流',gun.current+' A')+info('当前 SOC',gun.soc+'%')+info('枪线温度',gun.cableTemp+' ℃')+info('电池温度',gun.batteryTemp+' ℃')+info('剩余充电时间',gun.remaining+' 分钟')+'</div>';if(state.detailTab==='订单信息')return simpleTable(['订单编号','用户','充电量 (kWh)','用户实付 (元)','订单状态'],orders.filter(function(order){return order.gunId===gun.id}).map(function(order){return [order.id,userById(order.userId).phone,String(order.quantity),money(order.paid),badge(order.status)]}));return simpleTable(['故障编号','故障类型','故障描述','发生时间','故障状态'],[['GZ2026082301','通信异常','设备心跳报文中断','2026-08-23 11:32',badge(gun.fault)]])}
    function userDetailBody(user){if(state.detailTab==='基础信息')return '<div class="info-grid">'+info('用户编号',user.id)+info('用户昵称',esc(user.nickname))+info('手机号',esc(user.phone))+info('所属地区',esc(user.region))+info('用户状态',badge(user.status))+info('注册时间',user.registered)+'</div>';if(state.detailTab==='钱包记录')return '<div class="callout" style="margin-bottom:15px">当前钱包余额：<strong>'+money(user.wallet)+' 元</strong></div>'+simpleTable(['业务时间','业务类型','金额 (元)','账户余额 (元)'],[['2026-08-25 09:12','钱包充值','+200.00',money(user.wallet)],['2026-08-24 18:26','充电消费','-38.60',money(user.wallet-38.6)]]);if(state.detailTab==='车辆与 VIN')return simpleTable(['车牌号码','车辆 VIN','即插即充','钱包校验','维护入口'],[[esc(user.plate),user.vin,badge(user.plug?'启用':'停用'),user.wallet>0?badge('正常'):badge('余额预警'),'<button class="btn-link" data-action="drawer" data-kind="user" data-id="'+user.id+'">编辑 VIN</button>']]);if(state.detailTab==='充电订单')return simpleTable(['订单编号','所属场站','充电量 (kWh)','实付金额 (元)','订单状态'],orders.filter(function(order){return order.userId===user.id}).map(function(order){return [order.id,esc(stationById(order.stationId).name),String(order.quantity),money(order.paid),badge(order.status)]}));return simpleTable(['活动名称','优惠类型','优惠金额 (元)','参与时间'],campaigns.slice(0,2).map(function(campaign){return [esc(campaign.name),esc(campaign.template),money(campaign.value),campaign.start]}))}
    function enterpriseDetailBody(company){var owned=orders.filter(function(order,index){return index%enterprises.length===enterprises.indexOf(company)}),ownedRecharge=recharges.filter(function(item){return item.owner===company.name});if(state.detailTab==='企业资料')return '<div class="info-grid">'+info('企业编号',company.id)+info('企业名称',esc(company.name))+info('联系人',esc(company.contact))+info('联系电话',esc(company.phone))+info('企业账户',badge(company.status))+info('创建时间',company.created)+info('预付余额',money(company.balance)+' 元')+info('余额预警阈值',money(company.threshold)+' 元')+info('单次充电限额',money(company.limit)+' 元')+'</div>';if(state.detailTab==='账户与充值')return (company.balance<company.threshold?'<div class="callout warning" style="margin-bottom:15px">企业预付余额低于预警阈值，请及时线下对公充值。</div>':'')+'<div style="display:flex;justify-content:flex-end;margin-bottom:13px"><button class="btn btn-primary" data-action="drawer" data-kind="enterprise-recharge" data-id="'+company.id+'">登记对公充值</button></div>'+simpleTable(['充值编号','充值金额 (元)','充值方式','操作时间','入账状态'],ownedRecharge.map(function(item){return [item.id,money(item.amount),esc(item.method),item.time,badge(item.status)]}));if(state.detailTab==='企业订单')return simpleTable(['订单编号','车牌号码','所属场站','充电量 (kWh)','订单金额 (元)','单次限额 (元)','订单状态'],owned.map(function(order){return [order.id,esc(order.plate),esc(stationById(order.stationId).name),String(order.quantity),money(order.paid),money(company.limit),badge(order.status)]}));if(state.detailTab==='企业退款')return simpleTable(['退款单号','关联订单','退款金额 (元)','退款来源','审批状态'],refunds.map(function(refund){return [refund.id,refund.orderId,money(refund.amount),esc(refund.source),badge(refund.status)]}));if(state.detailTab==='企业车辆')return simpleTable(['车牌号码','车辆 VIN','司机','即插即充','单次限额 (元)'],users.slice(0,4).map(function(user){return [esc(user.plate),user.vin,esc(user.nickname),badge(user.plug?'启用':'停用'),money(company.limit)]}));return simpleTable(['订单日期','充电订单数','充电电量 (kWh)','电费 (元)','服务费 (元)','退款 (元)','预付账户余额 (元)'],[['2026-08-25',String(owned.length),money(owned.reduce(function(sum,item){return sum+item.quantity},0)),money(owned.reduce(function(sum,item){return sum+item.electricity},0)),money(owned.reduce(function(sum,item){return sum+item.service},0)),money(owned.reduce(function(sum,item){return sum+item.refund},0)),money(company.balance)]])}
    function renderDetail(){var d=state.detail,body='',tabs=[];if(d.kind==='station'){tabs=['基础信息','设备监控','收费方案','充电订单','操作记录'];body=stationDetailBody(stationById(d.id))}else if(d.kind==='pile'){tabs=['设备信息','充电枪','充电订单','日志记录'];body=pileDetailBody(pileById(d.id))}else if(d.kind==='gun'){tabs=['设备信息','订单信息','故障记录'];body=gunDetailBody(guns.find(function(item){return item.id===d.id}))}else if(d.kind==='order'){tabs=['订单信息','分时计费','优惠与支付','手续费与分账','退款记录'];body=orderDetailBody(orderById(d.id))}else if(d.kind==='user'){tabs=['基础信息','钱包记录','车辆与 VIN','充电订单','参与活动'];body=userDetailBody(userById(d.id))}else if(d.kind==='enterprise'){tabs=['企业资料','账户与充值','企业订单','企业退款','企业车辆','企业财务'];body=enterpriseDetailBody(enterprises.find(function(item){return item.id===d.id}))}else if(d.kind==='campaign'){var campaign=campaigns.find(function(item){return item.id===d.id});tabs=['活动信息','参与场站','效果数据'];if(state.detailTab==='活动信息')body='<div class="info-grid">'+info('活动名称',esc(campaign.name))+info('活动标题',esc(campaign.title))+info('活动模板',esc(campaign.template))+info('优惠范围',esc(campaign.fee))+info('活动对象',esc(campaign.audience))+info('活动状态',badge(campaign.status))+info('活动时间',campaign.start+' 至 '+campaign.end)+info('活动预算',money(campaign.budget)+' 元')+info('已使用预算',money(campaign.used)+' 元')+'</div>';else if(state.detailTab==='参与场站')body=simpleTable(['站点编号','站点名称','所属运营商','站点状态'],campaign.stations.map(function(id){var station=stationById(id);return [id,esc(station.name),esc(station.operator),badge(station.status)]}));else body='<div class="info-grid">'+info('参与人数',String(campaign.people))+info('优惠发放',money(campaign.used)+' 元')+info('预算剩余',money(campaign.budget-campaign.used)+' 元')+'</div>'}else return;$('content').innerHTML='<div class="detail-top"><div class="detail-ident"><button class="btn" data-action="back">‹ 返回</button><h2>'+esc(d.title)+'</h2><span class="code">'+esc(d.id)+'</span></div><button class="btn" data-action="drawer" data-kind="'+d.kind+'" data-id="'+esc(d.id)+'">编辑</button></div><section class="surface">'+tabsMarkup(tabs)+'<div class="detail-content">'+body+'</div></section>'}
    function openDetail(kind,id,tab){var record,title,first;if(kind==='station'){record=stationById(id);title=record.name;first='基础信息'}else if(kind==='pile'){record=pileById(id);title=record.name;first='设备信息'}else if(kind==='gun'){record=guns.find(function(item){return item.id===id});title=record.id;first='设备信息'}else if(kind==='order'){record=orderById(id);title='充电订单详情';first='订单信息'}else if(kind==='user'){record=userById(id);title=record.nickname;first='基础信息'}else if(kind==='enterprise'){record=enterprises.find(function(item){return item.id===id});title=record.name;first='企业资料'}else if(kind==='campaign'){record=campaigns.find(function(item){return item.id===id});title=record.name;first='活动信息'}if(!record)return;state.detail={kind:kind,id:id,title:title};state.detailTab=tab||first;render()}
    function ratesFromPeriods(periods){var result={};['尖','峰','平','谷'].forEach(function(kind){var period=periods.find(function(item){return item.kind===kind})||defaultPeriods.find(function(item){return item.kind===kind});result[kind]={electricity:Number(period.electricity),service:Number(period.service)}});return result}
    function rateEditor(){return '<div class="rate-grid"><div class="rate-row heading"><span>价格类别</span><span>电费</span><span>服务费</span></div>'+['尖','峰','平','谷'].map(function(kind){var rate=state.rates[kind];return '<div class="rate-row"><span class="rate-kind">'+kind+'</span><div class="input-unit"><input class="input" type="number" min="0" step="0.0001" data-rate-kind="'+kind+'" data-rate-field="electricity" value="'+rate.electricity.toFixed(4)+'"><span>元/kWh</span></div><div class="input-unit"><input class="input" type="number" min="0" step="0.0001" data-rate-kind="'+kind+'" data-rate-field="service" value="'+rate.service.toFixed(4)+'"><span>元/kWh</span></div></div>'}).join('')+'</div>'}
    function periodEditor(){return '<div class="period-coverage"><span>全天时段需连续覆盖 00:00—24:00，同一价格类别可配置多个时段</span><strong>按时间顺序配置</strong></div><div class="period-row heading"><span>价格类别</span><span>开始时间</span><span>结束时间</span><span></span></div><div id="periodRows">'+state.periods.map(function(item,index){return '<div class="period-row"><select class="select" data-period="kind" data-index="'+index+'">'+optionList(['尖','峰','平','谷'],item.kind)+'</select><input class="input" type="time" data-period="start" data-index="'+index+'" value="'+item.start.replace('24:00','23:59')+'"><input class="input" '+(item.end==='24:00'?'type="text" readonly':'type="time"')+' data-period="end" data-index="'+index+'" value="'+item.end+'"><button class="period-remove" data-action="remove-period" data-index="'+index+'">×</button></div>'}).join('')+'</div><button class="btn btn-soft" data-action="add-period" style="margin-top:9px">＋ 添加时间区间</button>'}
    function stationForm(record){var item=record||{name:'',operator:'',type:'公共',facility:'产业园区',region:'',address:'',hours:'06:00 - 23:00',status:'正常',plan:'',tags:[]};return '<div class="form-section">场站基础信息</div><div class="form-grid">'+formInput('f-name','站点名称',item.name,true)+formSelect('f-operator','所属运营商',operators,item.operator,true)+formSelect('f-type','站点类型',['公共','个人','公交（专用）','其他'],item.type,true)+formSelect('f-facility','场地类型',['居民区','产业园区','商业综合体','公共机构','公共停车场','景区停车场','写字楼','交通枢纽','其他'],item.facility,true)+formInput('f-region','所属区域',item.region,true,'text',true)+formInput('f-address','详细地址',item.address,true,'text',true)+formInput('f-hours','营业时间',item.hours,true)+formSelect('f-status','运行状态',['正常','维护中','下线','建设中'],item.status,true)+formSelect('f-plan','收费方案',plans.map(function(plan){return plan.name}),item.plan,false,true)+'</div><div class="form-section">站点标签</div><div class="choices">'+['商圈','超充站','企业专用','地库','景区'].map(function(tag){return '<label class="choice"><input type="checkbox" class="f-tag" value="'+tag+'" '+(item.tags.indexOf(tag)!==-1?'checked':'')+'>'+tag+'</label>'}).join('')+'</div><div class="form-section">地图选点</div><div class="map-demo" id="mapDemo"><span class="map-pin" id="mapPin"></span></div><div class="form-section">站点图片</div><label class="upload"><input id="f-images" type="file" accept="image/*" multiple style="display:none">＋ 上传站点图片</label><div class="form-section">绑定充电桩</div><div class="choices">'+piles.slice(0,8).map(function(pile){return '<label class="choice"><input type="checkbox" '+(record&&pile.stationId===record.id?'checked':'')+'>'+esc(pile.id)+'</label>'}).join('')+'</div>'}
    function planForm(record){var item=record||{name:'',operator:''};state.periods=(record?record.periods:defaultPeriods).map(function(period){return Object.assign({},period)});state.rates=ratesFromPeriods(state.periods);return '<div class="callout pricing-editor-intro">收费方案作为可复用价格模板保存；场站应用与预约生效统一在“预约调价”中配置。</div><div class="form-section">方案信息</div><div class="form-grid">'+formInput('f-name','方案名称',item.name,true)+formSelect('f-operator','所属运营商',operators,item.operator,true)+'</div><div class="form-section">价格类别</div>'+rateEditor()+'<div class="form-section">24 小时时段配置</div><div id="periodEditor">'+periodEditor()+'</div>'}
