    function openModal(title,body,actions){$('modalTitle').textContent=title;$('modalBody').innerHTML=body;$('modalActions').innerHTML=(actions||[]).map(function(action){return '<button class="btn '+(action.primary?'btn-primary':'')+' '+(action.danger?'btn-danger':'')+'" data-action="'+action.action+'" '+(action.id?'data-id="'+esc(action.id)+'"':'')+' '+(action.kind?'data-kind="'+esc(action.kind)+'"':'')+'>'+esc(action.label)+'</button>'}).join('');$('modalOverlay').classList.remove('hidden')}
